// Generates src/lib/services/recording/libopus-wasm-binary.ts: the libopus WebAssembly build from
// `@evan/opus` (plain `wasm/opus.wasm`, not `simd.wasm`, because SIMD is missing from some Safari
// builds) embedded as a base64 string, so the Angular library can hand it to its encoder Worker
// without shipping a separate asset that every host app would have to copy.
//
// Usage (from the package directory):
//   node scripts/embed-libopus-wasm.mjs <path-to-opus.wasm>
// Re-run it only when the wasm build is upgraded, and commit the regenerated file.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Characters per string literal line; keeps the generated file readable in editors and diffs. */
const CHUNK_CHARS = 1000;

const wasmPath = process.argv[2];
if (!wasmPath) {
    console.error('Usage: node scripts/embed-libopus-wasm.mjs <path-to-opus.wasm>');
    process.exit(1);
}

const bytes = readFileSync(wasmPath);
// "\0asm" magic: refuse to embed something that is not a WebAssembly module.
if (bytes.length < 8 || bytes[0] !== 0x00 || bytes[1] !== 0x61 || bytes[2] !== 0x73 || bytes[3] !== 0x6d) {
    console.error(`Not a WebAssembly module: ${wasmPath}`);
    process.exit(1);
}

const base64 = bytes.toString('base64');
const sha256 = createHash('sha256').update(bytes).digest('hex');
const lines = [];
for (let i = 0; i < base64.length; i += CHUNK_CHARS) {
    lines.push(`    '${base64.slice(i, i + CHUNK_CHARS)}',`);
}

const output = `/* eslint-disable */
// GENERATED by scripts/embed-libopus-wasm.mjs. Do not edit by hand; re-run the script instead.
//
// libopus compiled to WebAssembly, from @evan/opus@1.0.3 (wasm/opus.wasm).
// ${bytes.length} bytes, sha256 ${sha256}
//
// @evan/opus is MIT licensed:
//   Copyright (c) 2021-present evanwashere
//   Permission is hereby granted, free of charge, to any person obtaining a copy of this software
//   and associated documentation files (the "Software"), to deal in the Software without
//   restriction, including without limitation the rights to use, copy, modify, merge, publish,
//   distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the
//   Software is furnished to do so, subject to the following conditions: The above copyright
//   notice and this permission notice shall be included in all copies or substantial portions of
//   the Software. THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
//   IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A
//   PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE
//   LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR
//   OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER
//   DEALINGS IN THE SOFTWARE.
//
// libopus is BSD licensed:
//   Copyright 2001-2011 Xiph.Org, Skype Limited, Octasic, Jean-Marc Valin, Timothy B. Terriberry,
//   CSIRO, Gregory Maxwell, Mark Borgerding, Erik de Castro Lopo
//   Redistribution and use in source and binary forms, with or without modification, are permitted
//   provided that the following conditions are met:
//   - Redistributions of source code must retain the above copyright notice, this list of
//     conditions and the following disclaimer.
//   - Redistributions in binary form must reproduce the above copyright notice, this list of
//     conditions and the following disclaimer in the documentation and/or other materials provided
//     with the distribution.
//   - Neither the name of Internet Society, IETF or IETF Trust, nor the names of specific
//     contributors, may be used to endorse or promote products derived from this software without
//     specific prior written permission.
//   THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS" AND ANY EXPRESS OR
//   IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND
//   FITNESS FOR A PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT OWNER OR
//   CONTRIBUTORS BE LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR
//   CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR
//   SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY
//   THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR
//   OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE
//   POSSIBILITY OF SUCH DAMAGE.

/** Base64 of the libopus WebAssembly module the encoder Worker instantiates. */
export const LIBOPUS_WASM_BASE64: string = [
${lines.join('\n')}
].join('');
`;

const here = dirname(fileURLToPath(import.meta.url));
const target = resolve(here, '../src/lib/services/recording/libopus-wasm-binary.ts');
writeFileSync(target, output);
console.log(`Wrote ${target} (${bytes.length} wasm bytes, ${base64.length} base64 chars, sha256 ${sha256})`);
